import sys, json
f = sys.argv[1]; lim = int(sys.argv[2]) if len(sys.argv)>2 else 600
n=0
for line in open(f):
    try: d = json.loads(line)
    except: continue
    m = d.get('message') or {}
    role = m.get('role') or d.get('type')
    c = m.get('content')
    ts = d.get('timestamp','')
    if isinstance(c, str):
        n+=1; print(f"[{n}] {ts} {role} TEXT: {c[:lim]}"); continue
    if not isinstance(c, list): continue
    for b in c:
        n+=1
        t = b.get('type')
        if t == 'text': print(f"[{n}] {ts} {role} TEXT: {b['text'][:lim*3]}")
        elif t == 'tool_use': print(f"[{n}] {ts} {role} TOOL {b.get('name')}: {json.dumps(b.get('input'))[:lim*2]}")
        elif t == 'tool_result':
            cc = b.get('content')
            if isinstance(cc, list): cc = ' '.join(x.get('text','') for x in cc if isinstance(x, dict))
            print(f"[{n}] {ts} RESULT: {str(cc)[:lim]}")
        elif t == 'thinking': pass
EOF
